1	import { afterAll, beforeAll, beforeEach, describe, expect, it } from 'vitest';
2	import type { FastifyInstance } from 'fastify';
3	import { createTestApp, resetDb } from './helpers/app.js';
4	
5	const HOUR = 3_600_000;
6	
7	function inHours(hours: number): string {
8	  return new Date(Date.now() + hours * HOUR).toISOString();
9	}
10	
11	describe('bookings', () => {
12	  let app: FastifyInstance;
13	  let roomId: string;
14	  let userId: string;
15	
16	  beforeAll(async () => {
17	    app = await createTestApp();
18	  });
19	
20	  afterAll(async () => {
21	    await app.close();
22	  });
23	
24	  beforeEach(async () => {
25	    await resetDb();
26	    const room = await app.inject({
27	      method: 'POST',
28	      url: '/rooms',
29	      payload: { name: 'Aurora', capacity: 6 },
30	    });
31	    roomId = room.json().id;
32	    const user = await app.inject({
33	      method: 'POST',
34	      url: '/users',
35	      payload: { name: 'Ada Lovelace', email: 'ada@example.com' },
36	    });
37	    userId = user.json().id;
38	  });
39	
40	  async function book(startHours: number, endHours: number, title = 'Sync') {
41	    return app.inject({
42	      method: 'POST',
43	      url: '/bookings',
44	      payload: { roomId, userId, title, startsAt: inHours(startHours), endsAt: inHours(endHours) },
45	    });
46	  }
47	
48	  it('creates a booking', async () => {
49	    const response = await book(24, 25);
50	    expect(response.statusCode).toBe(201);
51	    expect(response.json().status).toBe('ACTIVE');
52	  });
53	
54	  it('rejects a payload without a title', async () => {
55	    const response = await app.inject({
56	      method: 'POST',
57	      url: '/bookings',
58	      payload: { roomId, userId, startsAt: inHours(24), endsAt: inHours(25) },
59	    });
60	    expect(response.statusCode).toBe(400);
61	    expect(response.json().error.code).toBe('VALIDATION_ERROR');
62	  });
63	
64	  it('rejects an instant that cannot be parsed', async () => {
65	    const response = await app.inject({
66	      method: 'POST',
67	      url: '/bookings',
68	      payload: { roomId, userId, title: 'Sync', startsAt: 'yesterday', endsAt: inHours(25) },
69	    });
70	    expect(response.statusCode).toBe(400);
71	  });
72	
73	  it('reads a booking back', async () => {
74	    const created = await book(24, 25);
75	    const response = await app.inject({ method: 'GET', url: `/bookings/${created.json().id}` });
76	    expect(response.statusCode).toBe(200);
77	    expect(response.json().title).toBe('Sync');
78	  });
79	
80	  it('answers 404 for a booking that does not exist', async () => {
81	    const response = await app.inject({ method: 'GET', url: '/bookings/missing' });
82	    expect(response.statusCode).toBe(404);
83	  });
84	
85	  it('lists bookings inside the page envelope', async () => {
86	    await book(24, 25);
87	    await book(30, 31, 'Retro');
88	    const response = await app.inject({ method: 'GET', url: '/bookings' });
89	    expect(response.json().data).toHaveLength(2);
90	    expect(response.json().pagination.total).toBe(2);
91	  });
92	
93	  it('filters bookings by room', async () => {
94	    await book(24, 25);
95	    const other = await app.inject({
96	      method: 'POST',
97	      url: '/rooms',
98	      payload: { name: 'Borealis', capacity: 4 },
99	    });
100	    await app.inject({
101	      method: 'POST',
102	      url: '/bookings',
103	      payload: {
104	        roomId: other.json().id,
105	        userId,
106	        title: 'Elsewhere',
107	        startsAt: inHours(24),
108	        endsAt: inHours(25),
109	      },
110	    });
111	    const response = await app.inject({ method: 'GET', url: `/bookings?roomId=${roomId}` });
112	    expect(response.json().data).toHaveLength(1);
113	  });
114	
115	  it('updates the title of a booking', async () => {
116	    const created = await book(24, 25);
117	    const response = await app.inject({
118	      method: 'PATCH',
119	      url: `/bookings/${created.json().id}`,
120	      payload: { title: 'Renamed' },
121	    });
122	    expect(response.statusCode).toBe(200);
123	    expect(response.json().title).toBe('Renamed');
124	  });
125	
126	  it('cancels a booking', async () => {
127	    const created = await book(24, 25);
128	    const response = await app.inject({
129	      method: 'POST',
130	      url: `/bookings/${created.json().id}/cancel`,
131	    });
132	    expect(response.statusCode).toBe(200);
133	    expect(response.json().status).toBe('CANCELLED');
134	  });
135	
136	  it('cancelling twice is idempotent', async () => {
137	    const created = await book(24, 25);
138	    const url = `/bookings/${created.json().id}/cancel`;
139	    await app.inject({ method: 'POST', url });
140	    const response = await app.inject({ method: 'POST', url });
141	    expect(response.statusCode).toBe(200);
142	    expect(response.json().status).toBe('CANCELLED');
143	  });
144	
145	  it('deletes a booking', async () => {
146	    const created = await book(24, 25);
147	    const id = created.json().id;
148	    expect((await app.inject({ method: 'DELETE', url: `/bookings/${id}` })).statusCode).toBe(204);
149	    expect((await app.inject({ method: 'GET', url: `/bookings/${id}` })).statusCode).toBe(404);
150	  });
151	
152	  it('rejects a booking whose start falls inside an active booking', async () => {
153	    await book(24, 25);
154	    const response = await book(24.5, 25.5, 'Overlap');
155	    expect(response.statusCode).toBe(409);
156	    expect(response.json().error.code).toBe('BOOKING_CONFLICT');
157	  });
158	
159	  it('rejects a booking fully contained in an active booking', async () => {
160	    await book(24, 25);
161	    const response = await book(24.1, 24.85, 'Inside');
162	    expect(response.statusCode).toBe(409);
163	  });
164	
165	  it('accepts a booking that starts exactly when another ends', async () => {
166	    await book(24, 25);
167	    const response = await book(25, 26, 'Adjacent');
168	    expect(response.statusCode).toBe(201);
169	  });
170	
171	  it('accepts a booking in a slot released by a cancellation', async () => {
172	    const first = await book(24, 25);
173	    await app.inject({ method: 'POST', url: `/bookings/${first.json().id}/cancel` });
174	    const response = await book(24.5, 25.5, 'Reused slot');
175	    expect(response.statusCode).toBe(201);
176	  });
